def transform(grid):
    """Extend incomplete horizontal foreground rows through their trailing background."""
    if not grid:
        return []
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        last = max((c for c, value in enumerate(row) if value != background), default=-1)
        if last >= 0:
            for c in range(last + 1, len(row)):
                out[r][c] = 1
    return out

